package com.silverroom.camera;
import java.util.*;import android.util.*;import android.graphics.ImageFormat;import android.hardware.camera2.*;import android.hardware.camera2.params.*;
public final class LogicalTrialProbe {
 static List<String> passed=new ArrayList<>();static void check(boolean yes,String name){if(!yes)throw new AssertionError(name);passed.add(name);}
 static CameraCharacteristics camera(int w,int h){CameraCharacteristics c=new CameraCharacteristics();StreamConfigurationMap map=new StreamConfigurationMap();for(int f:new int[]{34,35,256})map.formats.put(f,new Size[]{new Size(640,480),new Size(w,h)});c.set(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP,map);c.set(CameraCharacteristics.CONTROL_ZOOM_RATIO_RANGE,new Range<Float>(.6f,10f));return c;}
 static TrialEngine engine(){TrialEngine e=new TrialEngine();e.fastWanted=true;e.logicalOwners.add("2");e.logicalOwners.add("5");e.manager.items.put("0",camera(4096,3072));e.manager.items.put("3",camera(2560,1920));e.manager.items.put("4",camera(3264,2448));for(String owner:e.logicalOwners){e.manager.items.put(owner,camera(4096,3072));for(int i=0;i<3;i++){int base=new int[]{23,14,85}[i];e.routes.add(new LensPlan.Route(owner,new String[]{"0","3","4"}[i],base,base,false,false));}}return e;}
 static void rejected(TrialEngine e,String id,String name)throws Exception{boolean rejected=false;try{LogicalCameraPlan.create(e.manager,id,e.routes,e.previewMode,e.maxTextureEdge);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,name);}
 public static List<String> run()throws Exception{
  TrialEngine e=engine();LogicalCameraPlan plan=LogicalCameraPlan.create(e.manager,"2",e.routes,0,4096);check(plan.preview.getWidth()==4096&&plan.jpeg.getWidth()==4096&&plan.physical.get(85).equals("4"),"Eligible logical output preserves all three optical groups and full baseline preview/JPEG sizes");check(plan.route(230).logicalZoom&&plan.route(230).base==85&&!plan.route(230).logicalDefault,"Experimental route identity is separate from default-main and stable profiles");
  e.manager.items.get("2").set(CameraCharacteristics.CONTROL_ZOOM_RATIO_RANGE,new Range<Float>(1f,10f));rejected(e,"2","A logical range without ultrawide coverage is rejected");e=engine();e.manager.items.get("2").set(CameraCharacteristics.CONTROL_ZOOM_RATIO_RANGE,new Range<Float>(.6f,5f));rejected(e,"2","A logical range without 230mm coverage is rejected");
  e=engine();e.manager.items.put("2",camera(1920,1080));rejected(e,"2","A lower resolution logical stream cannot silently replace the clear preview");
  e=engine();e.manager.items.get("2").get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP).formats.remove(ImageFormat.JPEG);rejected(e,"2","A preview-only logical device cannot pass the JPEG eligibility gate");
  e=engine();e.routes.removeIf(r->r.owner.equals("2")&&r.base==85);rejected(e,"2","Incomplete physical metadata is not guessed from numerical camera IDs");
  e=engine();check(e.chooseForTest().owner.equals("2"),"Candidate order retains discovered standard-before-extended ordering");e.logicalPlan=e.chooseForTest();e.failForTest("configure rejected");check(!e.logicalRejected.isEmpty()&&e.fastReason.isEmpty()&&e.opens==1&&e.chooseForTest().owner.equals("5"),"An unproved candidate failure advances once to the next candidate without poisoning stable routes");
  e.logicalPlan=e.chooseForTest();e.failForTest("second rejected");check(e.chooseForTest()==null&&!e.fastReason.isEmpty()&&e.fastPreferences.data.containsKey(e.fastKey),"Exhausting logical candidates persists a blocked status instead of repeated startup retries");
  e=engine();e.logicalPlan=e.chooseForTest();e.logicalEstablished=true;e.targetMm=230;e.failForTest("wrong physical ID");check(e.requestedMm==230&&e.chooseForTest()==null&&e.closes==1&&e.opens==1&&e.fastStatus().startsWith("已回退"),"A runtime optical mismatch returns to the latest requested optical focal and suspends the experiment");
  e=engine();e.logicalPlan=e.chooseForTest();e.captureInFlight=true;e.failForTest("unverified JPEG");check(e.listener.error!=null&&e.fastReason.contains("unverified")&&!e.captureInFlight,"Failed still verification reports no saved photo and leaves capture state recoverable");
  e=engine();e.rawWanted=true;check(e.chooseForTest()==null&&e.logicalRejected.isEmpty()&&e.fastStatus().contains("RAW"),"RAW pauses the trial without rejecting metadata or silently disabling RAW");
  e=engine();e.captureInFlight=true;e.deferredRaw=true;e.deferredFast=false;e.deferredQuality=1;check(!e.settingsForTest()&&!e.rawWanted&&e.fastWanted&&e.closes==0,"RAW, mode and quality changes wait for the current capture");e.captureInFlight=false;check(e.settingsForTest()&&e.rawWanted&&!e.fastWanted&&e.previewMode==1&&e.closes==1&&e.opens==1,"Deferred settings apply together with a single rebuild after capture");
  e=engine();e.fastReason="blocked";e.fastPreferences.data.put(e.fastKey,"blocked");e.logicalRejected.add("2");e.retryFastPending=true;e.settingsForTest();check(e.fastReason.isEmpty()&&e.logicalRejected.isEmpty()&&!e.fastPreferences.data.containsKey(e.fastKey),"Explicit retry clears only the dedicated trial block and candidate failures");
  e=engine();e.active=false;e.deferredFast=false;e.settingsForTest();check(e.opens==0&&!e.fastWanted,"Changing experiment settings in the background cannot open a camera");
  e=engine();e.logicalPlan=e.chooseForTest();e.logicalEstablished=true;e.captureInFlight=true;e.logicalJpeg=new LogicalJpegGate();e.logicalJpegResult=new Object();e.rawCapture=new TrialEngine.RawCapture();e.logicalJpeg.image(100,new byte[1]);e.finishForTest();check(e.rawCapture.photos==0&&e.rawCapture.results==0,"Shipping JPEG handoff never supplies image-only data to the permissive legacy saver");e.logicalJpeg.result(100,true);e.finishForTest();e.finishForTest();check(e.rawCapture.photos==1&&e.rawCapture.results==1,"Shipping verified JPEG handoff supplies paired metadata and bytes exactly once");
  e=engine();e.logicalPlan=e.chooseForTest();e.logicalEstablished=true;e.captureInFlight=true;e.logicalJpeg=new LogicalJpegGate();e.rawCapture=new TrialEngine.RawCapture();e.logicalJpeg.image(1,new byte[1]);e.logicalJpeg.result(2,true);e.finishForTest();check(e.rawCapture.photos==0&&e.fastStatus().startsWith("已回退"),"Mismatched still timestamps trigger shipping recovery before any gallery save");
  e=engine();e.logicalPlan=e.chooseForTest();android.os.Build.VERSION.SDK_INT=36;OutputConfiguration output=e.outputForTest();check(output.base==OutputConfiguration.TIMESTAMP_BASE_SENSOR&&!output.readout,"Logical preview/JPEG use sensor exposure timestamps for exact metadata pairing on API 36");
  android.os.Build.VERSION.SDK_INT=30;output=e.outputForTest();check(output.base==-1&&output.readout,"Older Android does not call newer output timestamp APIs");
  android.os.Build.VERSION.SDK_INT=36;e.logicalPlan=null;e.route=new LensPlan.Route("2","4",85,85,false,false);output=e.outputForTest();check(output.physical.equals("4")&&output.base==-1&&output.readout,"Stable physical output bindings and timestamp defaults stay unchanged");
  int[] all={0,1,2,3};check(FlickerControl.choose(0,all,all)==3&&FlickerControl.choose(1,all,all)==1&&FlickerControl.choose(2,all,all)==2,"Automatic and both mains frequencies map to the advertised Camera2 anti-banding values");
  check(FlickerControl.choose(1,new int[]{3},all)==3&&FlickerControl.choose(2,all,new int[]{3})==3,"Unsupported fixed frequencies fall back to AUTO only when both sensor and owner advertise it");
  check(FlickerControl.choose(0,null,all)==-1&&FlickerControl.choose(1,new int[]{0},new int[]{0})==-1,"Missing or unsupported metadata never invents an anti-banding mode");
  check(FlickerControl.safe(99)==0&&FlickerControl.status(0,-1).contains("不支持"),"Invalid saved frequency falls back to AUTO and unsupported requests are described honestly");
  e=engine();e.chars.set(CameraCharacteristics.CONTROL_AE_AVAILABLE_ANTIBANDING_MODES,all);e.ownerChars.set(CameraCharacteristics.CONTROL_AE_AVAILABLE_ANTIBANDING_MODES,all);CaptureRequest.Builder request=new CaptureRequest.Builder();e.antibandingForTest(request);check(request.values.get(CaptureRequest.CONTROL_AE_ANTIBANDING_MODE).equals(3)&&e.physicalMode==3,"Shipping controls explicitly request AUTO on both logical/global and supported physical controls");
  e.antibanding(1);request=new CaptureRequest.Builder();e.antibandingForTest(request);check(request.values.get(CaptureRequest.CONTROL_AE_ANTIBANDING_MODE).equals(1)&&e.updates==1&&e.closes==0&&e.opens==0,"Selecting 50Hz updates the current request without closing the fast camera session");
  e.chars.set(CameraCharacteristics.CONTROL_AE_AVAILABLE_ANTIBANDING_MODES,new int[]{3});e.antibandingForTest(request);check(request.values.get(CaptureRequest.CONTROL_AE_ANTIBANDING_MODE).equals(3)&&e.antibandingStatus().contains("使用自动"),"Fixed-frequency fallback is reflected in the settings status");
  e.chars.set(CameraCharacteristics.CONTROL_AE_AVAILABLE_ANTIBANDING_MODES,null);request=new CaptureRequest.Builder();e.antibandingForTest(request);check(request.values.isEmpty()&&e.antibandingStatus().contains("不支持"),"A lens without anti-banding support receives no unsupported capture key");
  return passed;
 }
}
